1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	};
45	const FIRST_INSURANCE_RATE = 0.1;
46	
47	const withFirstInsuranceSurcharge = (basePremium: number): number =>
48	  basePremium + basePremium * FIRST_INSURANCE_RATE;
49	
50	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
51	
52	const quotePremium = (items: Item[]): number =>
53	  withFirstInsuranceSurcharge(
54	    items.reduce((sum, item) => sum + basePremiumOf(item), 0),
55	  ) + PROCESSING_FEE;
56	
57	const runStep = (step: Step): StepResult => {
58	  if (step.op === "quote") return { premium: quotePremium(step.items) };
59	  throw new Error(`unsupported step: ${step.op}`);
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResult => ({
63	  results: scenario.steps.map(runStep),
64	});
